-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.answered_decks()
 RETURNS TABLE(deck_id text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select distinct s.deck_id
    from public.card_states s
   where s.user_id = auth.uid() and (s.phase <> 'new' or s.reps > 0) and s.retired_at is null;
$function$;

grant execute on function public.answered_decks() to authenticated;
grant execute on function public.answered_decks() to service_role;
